// Function to check if pieces are in a straight line (horizontally, vertically, diagonally)
func arePiecesInLine(pieces [][]int, x, y int) bool {
	lines := make([][]int, 4)

	// Horizontal (one knight at the given position)
	lines[0] = append(lines[0], x, y, x, y, x, y, x, y)

	// Vertical
	lines[1] = append(lines[1], x, y, x+1, y, x+2, y, x+3, y, x+4, y, x+5, y)

	// Poslakov (one knight at the given position)
	lines[2] = append(lines[2], x, y, x+1, y+1, x+2, y+2, x+3, y+3, x+4, y+4, x+5, y+5)

	// Posokakov (one knight at the given position)
	lines[3] = append(lines[3], x, y, x-1, y+1, x-2, y+2, x-3, y+3, x-4, y+4, x-5, y+5)

	return checkLine(lines, pieces)
}

// Helper function to check if pieces are in a line
func checkLine(lines [][]int, pieces [][]int) bool {
	for _, line := range lines {
