def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def has_prime_digit_sum(number):
    digits = [int(digit) for digit in str(number)]
    for i in range(len(digits)):
        for j in range(i + 1, len(digits)):
            if not is_prime(digits[i] + digits[j]):
                return False
    return True

# We can start checking from 9999 downwards because we want the largest number
