import itertools

def is_valid_seq(seq):
    if set(seq) not in [{0}, {1}, {0, 1}, {0, 0}, {1, 1}]:
        return False
    for i in range(len(seq) - 2):
        if seq[i] == seq[i + 1] == seq[i + 2]:
            return False
    return True

def count_valid_sequences(n):
    valid_seqs = 0
    for seq in itertools.product([0, 1], repeat=n):
